/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def format_rag_knowledge_response(
    db_results: list, trigger_data: dict
) -> dict:
    """
    تنسيق نتائج قاعدة المعرفة في سياق RAG لتوليد الرد المبني على الحقائق.

    Processes knowledge base query results into RAG context for the
    grounded LLM response generation step.

    Args:
        db_results: Rows from the knowledge_base table with relevance scores.
        trigger_data: Original trigger data with customer message and locale.

    Returns:
        Dict with rag_context, status, and metadata.
    """
    locale = trigger_data.get("locale", "ar")
    is_ar = locale == "ar"
    customer_msg = trigger_data.get("customer_message") or trigger_data.get("sanitized_message", "")

    relevant = [r for r in db_results if r and r.get("relevance_score", 0) > 0]

    if relevant:
        context_parts = []
        for kb in relevant:
            q = (kb.get("question_ar") or kb.get("question", "")) if is_ar else (kb.get("question") or kb.get("question_ar", ""))
            a = (kb.get("answer_ar") or kb.get("answer", "")) if is_ar else (kb.get("answer") or kb.get("answer_ar", ""))
            context_parts.append(f"سؤال: {q}\nإجابة: {a}")
        context = "\n---\n".join(context_parts)

        return {
            "status": "rag_context_found",
            "intent_handled": "faq_query",
            "rag_context": context,
            "customer_message": customer_msg,
            "locale": locale,
            "top_category": relevant[0].get("category"),
            "relevance_score": relevant[0].get("relevance_score"),
        }
    else:
        return {
            "status": "no_context",
            "intent_handled": "faq_query",
            "rag_context": "",
            "customer_message": customer_msg,
            "locale": locale,
            "relevance_score": 0,
        }


# ==============================================================================
# 10. WORKFLOW 04B — Guardrail & Professional Formatter
# Node: "Guardrail & Professional Formatter"
# Purpose: Final formatting of the RAG-grounded LLM response. Applies hard
#          guardrails when no relevant FAQ was found (out-of-scope deflection).
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const results = ($input.first()?.json || []);
const rows = Array.isArray(results) ? results : (results.results || [results]);
const triggerData = $('Execute Workflow Trigger').first()?.json || {};
const locale = triggerData.locale || 'ar';
const isAr = locale === 'ar';
const customerMsg = triggerData.customer_message || triggerData.sanitized_message || '';

// Filter results with relevance > 0
const relevant = rows.filter(r => r && r.relevance_score > 0);

if (relevant.length > 0) {
  // Build context from top matching FAQ entries
  const contextParts = relevant.map(kb => {
    const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
    const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
    return `سؤال: ${q}\nإجابة: ${a}`;
  });
  const context = contextParts.join('\n---\n');

  return [{
    json: {
      status: 'rag_context_found',
      intent_handled: 'faq_query',
      rag_context: context,
      customer_message: customerMsg,
      locale: locale,
      top_category: relevant[0].category,
      relevance_score: relevant[0].relevance_score
    }
  }];
} else {
  // No relevant FAQ found - will trigger guardrail
  return [{
    json: {
      status: 'no_context',
      intent_handled: 'faq_query',
      rag_context: '',
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0
    }
  }];
}

/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def guardrail_and_professional_formatter(
    rag_data: dict, qwen_output: dict
) -> dict:
    """
    التنسيق النهائي للرد المبني على قاعدة المعرفة مع حماية ضد الخروج عن النطاق.

    Final formatting with hard guardrails for out-of-scope deflection
    and WhatsApp-friendly markdown cleanup.

    Args:
        rag_data: Output from the RAG knowledge formatting step.
        qwen_output: Raw output from the Qwen RAG LLM call.

    Returns:
        Dict with formatted reply, status, and sources.
    """
    locale = rag_data.get("locale", "ar")
    is_ar = locale == "ar"

    if rag_data.get("status") == "no_context" or rag_data.get("relevance_score", 0) == 0:
        final_reply = (
            "عذراً، هذا الاستفسار خارج نطاق خدماتنا المعتمدة حالياً.\n\n"
            "يسعدني مساعدتك في الاستفسار عن:\n"
            "📌 مبادرة الرواد الرقميون (DEPI)\n"
            "📝 شروط التقديم والتسجيل\n"
            "🎓 نظام الدراسة والامتحانات\n"
            "🏆 التخصصات المتاحة\n"
            "⏱️ الدعم الفني\n\n"
            "أو يمكنك طلب التحدث مع ممثل خدمة العملاء."
            if is_ar
            else "Sorry, this inquiry is outside our current service scope."
        )
        status = "out_of_scope"
        sources = ["Guardrail: Out of Scope"]
    else:
        final_reply = qwen_output.get("response") or rag_data.get("rag_context", "")
        final_reply = re.sub(r"\*\*", "*", final_reply)
        final_reply = re.sub(r"^#+\s*", "", final_reply, flags=re.MULTILINE)
        final_reply = final_reply.strip()
        status = "success"
        sources = [f"MCIT Official Knowledge Base - {rag_data.get('top_category', 'General')}"]

    return {
        "status": status,
        "intent_handled": "faq_query",
        "category": rag_data.get("top_category", "general"),
        "reply": final_reply,
        "sources": sources,
    }


# ==============================================================================
# 11. WORKFLOW 04C — Format Escalation Notice
# Node: "Format Escalation Notice"
# Purpose: Formats a professional bilingual escalation notification with
#          the generated ticket number and SLA priority.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenOutput = $input.first()?.json || {};
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';

let finalReply = '';

if (ragData.status === 'no_context' || ragData.relevance_score === 0) {
  // Hard guardrail: no relevant FAQ found
  finalReply = isAr
    ? 'عذراً، هذا الاستفسار خارج نطاق خدماتنا المعتمدة حالياً.\n\nيسعدني مساعدتك في الاستفسار عن:\n📌 مبادرة الرواد الرقميون (DEPI)\n📝 شروط التقديم والتسجيل\n🎓 نظام الدراسة والامتحانات\n🏆 التخصصات المتاحة\n⏱️ الدعم الفني\n\nأو يمكنك طلب التحدث مع ممثل خدمة العملاء.'
    : 'Sorry, this inquiry is outside our current service scope.\n\nI can help you with:\n📌 Digital Pioneers Initiative (DEPI)\n📝 Admissions & Registration\n🎓 Study & Exams System\n🏆 Available Tracks\n⏱️ Support\n\nOr you may request to speak with a human specialist.';
} else {
  // Use Qwen's grounded response
  finalReply = qwenOutput.response || ragData.rag_context || '';

  // Clean up any markdown artifacts that don't render well in WhatsApp
  finalReply = finalReply.replace(/\*\*/g, '*').replace(/^#+\s*/gm, '').trim();
}

return [{
  json: {
    status: ragData.status === 'no_context' ? 'out_of_scope' : 'success',
    intent_handled: 'faq_query',
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: ragData.status === 'no_context' ? ['Guardrail: Out of Scope'] : ['MCIT Official Knowledge Base - ' + (ragData.top_category || 'General')]
  }
}];
